when.set-body:
@{
                try
                {
                    var response = context.Response.Body?.As();
                    var message = response?.Value("message")
                        ?? response?["odata.error"]?["message"]?["value"]?.Value();

                    var result = new JObject
                    {
                        ["statusCode"] = context.Response.StatusCode,
                        ["message"] = !string.IsNullOrWhiteSpace(message) ? message : context.Response.StatusReason
                    };
                    return result.ToString();
                }
                catch
                {
                    // Ignore parsing error when e.g. the response is not JSON, fallback to default message
                    return new JObject
                    {
                        ["statusCode"] = context.Response.StatusCode,
                        ["message"] = context.Response.StatusReason
                    }.ToString();
                }
            }
